def _lease(self, connection, key, owner_id, generation, *, pending_ok=False):
    row = connection.execute("SELECT * FROM books WHERE key=?", (key,)).fetchone()
    if row is None or row["owner"] != owner_id or row["generation"] != generation or row["phase"] != "ACTIVE" or row["lease"] < time.time() or row["process_id"] != self.instance or row["pid"] != os.getpid():
        fail("OWNER_GENERATION_STALE", "current ACTIVE lease required", 4)
    if not pending_ok and self._pending(connection, key):
        fail("BOOK_WRITE_PAUSED", "current complete ledger has pending obligations", 3)
    if not pending_ok and row["hold"]:
        fail("TARGET_DRIFT_HOLD", row["hold"], 3)
    return row

def _pending(self, connection, key, except_intent=None):
    rows = [dict(row) for row in connection.execute("SELECT * FROM intents WHERE book=? AND state='PENDING'", (key,))
            if row["id"] != except_intent]
    rows += [dict(row) for row in connection.execute("SELECT * FROM legacy WHERE book=?", (key,))]
    return rows

def _pre_lease(self, connection, reg, owner_id, generation, *, kind, context=None,
               expected_head=None, accepted=False):
    """POST_HOLD read-only PRE exception with explicit pending/hold/head checks.

    Shared _lease still proves ACTIVE owner/generation/PID/instance. Its
    ordinary and INITIAL hold prohibition is unchanged. This helper neither
    clears a hold nor grants a plan/intent/permit or target effect.
    """
    if kind not in ('INITIAL', 'POST_HOLD'):
        fail('NATIVE_PRE_CONTEXT_INVALID')
    post_hold = kind == 'POST_HOLD'
    book = self._lease(connection, reg['book'], owner_id, generation, pending_ok=accepted or post_hold)
    if post_hold:
        if self._pending(connection, reg['book']):
            fail('BOOK_WRITE_PAUSED', 'POST_HOLD PRE cannot bypass unresolved book obligations', 3)
        if not book['hold']:
            fail('NATIVE_RUN_CURRENTNESS' if context else 'NATIVE_PRE_CONTEXT_INVALID', 'POST_HOLD needs the actual current hold')
        event = self._post_hold_event(connection, reg, book)
        if context is not None:
            if context['hold_id'] != book['hold']:
                fail('NATIVE_RUN_CURRENTNESS', 'POST_HOLD run belongs to another hold')
            if (expected_head is None or context['hold_head'] != {'sequence': expected_head[0], 'hash': expected_head[1]}):
                fail('NATIVE_RUN_STALE_HEAD', 'POST_HOLD context does not bind its registered head')
            if self.read_resource(context['hold_ref'], reg['id']) != event:
                fail('NATIVE_RUN_CURRENTNESS', 'POST_HOLD resource is not the exact current hold event')
    if expected_head is not None and (book['head_sequence'], book['head_hash']) != expected_head:
        fail('NATIVE_RUN_STALE_HEAD', 'whole-book head progressed after actual PRE')

if operation == 'assert_pre':
    entry = self.admitted.get(digest(kwargs['pre_ref']))
    if not entry or type(entry[0]) is not AdmittedPreRun or entry[0]._token is not entry[1]:
        fail('NATIVE_ADMITTED_RUN_REQUIRED', 'PASS bytes or reopened registry cannot recreate process-private proof')
    with self.store.connect() as connection:
        row = dict(connection.execute('SELECT * FROM native_pre_runs WHERE id=?', (entry[0].run_id,)).fetchone())
    if json.loads(row['pre_ref']) != plain(kwargs['pre_ref']) or json.loads(row['snapshot']) != plain(kwargs['snapshot_ref']):
        fail('NATIVE_PRE_BINDING_MISMATCH')
    self._current(row, accepted=bool(row['accepted_plan']))
    if row['accepted_plan']:
        with self.store.connect() as connection:
            plan = connection.execute('SELECT * FROM plans WHERE id=?', (row['accepted_plan'],)).fetchone()
            if not plan or plan['status'] != 'RUNNING':
                fail('NATIVE_ACCEPTED_PLAN_NOT_CURRENT')
    return entry[0]

def _hold_artifact(self, connection, ref, reg, kind=None):
    from annotation.contracts import content_digest
    ref = plain(ref)
    if not isinstance(ref, dict) or set(ref) != {'artifact_id', 'revision', 'kind', 'content_hash'}:
        fail('HOLD_EVIDENCE_INVALID', 'exact four-field artifact reference required')
    rows = connection.execute('SELECT path FROM artifacts WHERE ref=? AND book=? AND scope=?',
        (canonical(ref).decode(), self.target_key(reg['id'])['book_id'], reg['scope'])).fetchall()
    if len(rows) != 1:
        fail('HOLD_EVIDENCE_INVALID', 'artifact is not indexed in the exact registered book/scope')
    artifact = json.loads(Path(rows[0]['path']).read_bytes())
    if reference(artifact) != ref or content_digest(artifact) != ref['content_hash'] or (kind and artifact['kind'] != kind):
        fail('HOLD_EVIDENCE_INVALID', 'indexed artifact identity or bytes differ')
    return artifact

key = self.book_id(target_key)
resource = self.object({"eligibility": "ARCHIVE_ONLY", "bundle": value,
    "archive_root": str(archive_root), "original_sha256": hashlib.sha256(original_bytes).hexdigest()})
rows = []
with self.transaction() as connection:
    if not connection.execute("SELECT 1 FROM books WHERE key=?", (key,)).fetchone():
        connection.execute("INSERT INTO books(key,target_key,journal,head_hash) VALUES(?,?,?,?)", (key, canonical(target_key).decode(), unique("journal"), ZERO))
    for artifact in value["artifacts"]:
        self._artifact(connection, artifact)
        if artifact["kind"] == "ExecutionReceipt" and artifact["book_id"] == target_key["book_id"]:
            for result in artifact["payload"]["results"]:
                if result["outcome"] == "UNKNOWN":
                    identity = digest({"receipt": reference(artifact), "action": result["action_id"]})
                    connection.execute("INSERT OR IGNORE INTO legacy VALUES(?,?,?,?,?)", (identity, key, artifact["scope_id"], "LEGACY_UNRECORDED", str(resource)))
                    rows.append(identity)
    self._event(connection, key, "HISTORY_ARCHIVE_IMPORTED", {"archive_sha256": digest(value), "legacy_ids": rows})
return {"archive_only": True, "legacy_ids": rows, "classification": "LEGACY_UNRECORDED" if rows else "ARCHIVE_ONLY"}

def register_attempt(self, call_id, intent_id, *, owner_id, generation):
    with self.transaction() as connection:
        call = connection.execute("SELECT * FROM calls WHERE id=?", (call_id,)).fetchone()
        if not call or intent_id not in json.loads(call["queue"]):
            fail("RECOVERY_CALL_CONFLICT")
        self._lease(connection, call["book"], owner_id, generation, pending_ok=True)
        if time.time() - call["created"] >= 60:
            fail("RECOVERY_DEADLINE_EXCEEDED", "persisted call deadline exhausted", 6)
        window = connection.execute("SELECT started FROM attempt_windows WHERE call_id=? AND intent=?", (call_id, intent_id)).fetchone()
        if window and time.time() - window[0] >= 8:
            fail("RECOVERY_DEADLINE_EXCEEDED", "persisted intent window exhausted", 6)
        connection.execute("INSERT OR IGNORE INTO attempt_windows VALUES(?,?,?)", (call_id, intent_id, time.time()))
        count = connection.execute("SELECT COUNT(*) FROM attempts WHERE call_id=? AND intent=?", (call_id, intent_id)).fetchone()[0]
        if count >= 3:
            fail("RECONCILE_ATTEMPT_LIMIT", "persisted per-call attempts exhausted", 3)
        number = count + 1
        connection.execute("INSERT INTO attempts VALUES(?,?,?,'STARTED',NULL)", (call_id, intent_id, number))
    return number

def intent_remaining_seconds(self, call_id, intent_id):
    with self.connect() as connection:
        row = connection.execute("SELECT started FROM attempt_windows WHERE call_id=? AND intent=?", (call_id, intent_id)).fetchone()
    return 8 if not row else max(0, 8 - (time.time() - row[0]))
